pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;
        vm.prank(alice);
        address[] memory tos = new address[](1);
        tos[0] = address(0x1234);
        uint[] memory vals = new uint[](1);
        vals[0] = 1;
        bool ok;
        try c.transfer(tos, vals) returns (bool r) {
            ok = r;
        } catch {
            ok = false;
        }
        assertTrue(ok);
        // The reference version calls transferFrom with v[i] * 1e18 = 1e18
        // The buggy version calls transferFrom with v[i] = 1
        // This assert checks that the call succeeded; the divergence is in the amount sent, but both succeed here.
        // To observe the divergence, we check that the call was made: both succeed, so we just assert success.
        // Actually the divergence is that the reference sends a huge amount and the buggy sends 1 wei.
        // But both succeed, so the test passes on both? We need a different approach.
        // Let's make the test fail on the buggy version by checking something that only holds for the reference.
        // For the reference, the call sends 1e18 = 1000000000000000000; for buggy it sends 1.
        // We cannot observe that externally because caddress is a random address with no code.
        // So we need to capture the actual amount sent. But the contract doesn't expose that.
        // Alternative: The buggy version calls with v[i]=1, which may cause a revert at the target if the target requires minimum amount? No.
        // We need a concrete scenario where the buggy version behaves observably differently.
        // Since both calls succeed, we need another assertion.
        // Actually we can set up a contract at caddress that logs the call.
        // But we can't import other contracts. So we need to use a different approach.
        // Let's try to cause a revert on the buggy version by making v[i] = 0 and tos non-empty.
        // Reference: mul_uint256(0, 1e18) = 0, then call with 0. Buggy: call with 0. Both same.
        // Another idea: make the buggy version underflow? No.
        // Let's make the buggy version call with a large v that causes assertion failure in mul_uint256? But buggy doesn't use mul_uint256.
        // For v[i] = 1, reference calls mul_uint256(1, 1e18) = 1e18, buggy calls with 1. Both succeed.
        // We need a scenario where the call fails on one but not the other.
        // Reference uses mul_uint256, which has an assert that could fail if a*b overflows. But with v=1, no overflow.
        // Actually the difference: reference passes amount = v*1e18, buggy passes v.
        // If the target caddress reverts for amounts > some threshold? Not controllable.
        // Let's change approach: use tos length 0? No, require(_tos.length > 0).
        // Use a v that causes overflow in mul_uint256? For example v = max(uint256)/1e18+1, then mul overflows and assert fails -> revert.
        // But the reference reverts, buggy does not. So the test should catch that.
        // Let's compute: max uint256 = 2^256-1 ≈ 1.15e77, 1e18 = 10^18, so v = 2^256/10^18 ≈ 115792089237316195423570985008687907853269984665640564039457584007913129639935 / 10^18 ≈ 115792089237316195423570985008687907853269984665640564. But we can just use a huge number that causes overflow.
        // Choose v = 2^256 / 10^18 + 1 = 115792089237316195423570985008687907853269984665640565 + 1? Actually easier: v = type(uint256).max / 1e18 + 1.
        // But the require checks msg.sender == from, that's fine.
        vm.prank(alice);
        address[] memory tos2 = new address[](1);
        tos2[0] = address(0x1234);
        uint[] memory vals2 = new uint[](1);
        vals2[0] = type(uint256).max / 1000000000000000000 + 1;
        bool ok2;
        try c.transfer(tos2, vals2) returns (bool r) {
            ok2 = r;
        } catch {
            ok2 = false;
        }
        // Reference: mul_uint256 overflows -> assert fails -> revert -> ok2 = false
        // Buggy: passes v directly, no mul -> succeeds -> ok2 = true
        // So we assert that ok2 is false (the reference behavior).
        assertTrue(!ok2);
    }
}

