// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up authorized caller
        address authorized = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;
        address[] memory tos = new address[](2);
        tos[0] = address(0xdead);
        tos[1] = address(0xbeef);
        uint[] memory vals = new uint[](2);
        vals[0] = 1;
        vals[1] = 2;

        // Deploy a mock contract that modifies the from address when delegatecalled
        // But since we cannot deploy another contract, we just call transfer
        // and check that the from address remains unchanged after call
        address fromBefore = c.from();
        vm.prank(authorized);
        (bool success,) = address(c).call(abi.encodeWithSignature("transfer(address[],uint256[])", tos, vals));
        require(success, "transfer call failed");
        address fromAfter = c.from();
        // In the reference (call), from should stay the same
        // In the modified version (delegatecall), from could be changed by the external contract
        // Since the external contract at caddress may or may not modify state, we need to
        // assert that from did NOT change; this holds for reference (call) but may fail for modified (delegatecall)
        assertEq(fromAfter, fromBefore);
    }
}

