pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Arrange: set up caller and call transfer
        address caller = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;
        address[] memory tos = new address[](1);
        tos[0] = address(0xdead);
        uint[] memory vals = new uint[](1);
        vals[0] = 1;

        vm.prank(caller);
        // The reference succeeds (call), the bug reverts or returns false (delegatecall)
        bool ok;
        try c.transfer(tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference: transfer succeeds => ok is true
        // Bug: delegatecall to a random address will likely revert or return false => ok false
        assertTrue(ok);
    }
}

